import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';

export const PRO_MANIFEST_FILE = 'pro.manifest.json';
export const PRO_RECORD_FILE = '.cdal/pro.json';

// Files carrying these markers were generated by `cdalkit sync`/`init` and can be regenerated,
// so Pro content may replace them; anything else in the project is user-owned.
const GENERATED_MARKERS = ['CDAL GENERATED', 'GENERATED by cdal sync'];

function isGeneratedFile(path: string): boolean {
  const content = readFileSync(path, 'utf8');
  return GENERATED_MARKERS.some((marker) => content.includes(marker));
}

export class ProInstallError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ProInstallError';
  }
}

export interface ProManifest {
  name: string;
  version: string;
  install: Array<{ from: string; to: string }>;
}

export interface ProInstallOptions {
  /** Directory containing pro.manifest.json (a clone of cdal-pro or a local copy). */
  sourceDir: string;
  /** Project root to install into. */
  targetDir: string;
  /** Overwrite files that already exist in the project. */
  force?: boolean;
  /** Report what would be written without touching the project. */
  dryRun?: boolean;
}

export interface ProInstallResult {
  name: string;
  version: string;
  /** Project-relative paths written (or, in dry-run mode, that would be written). */
  written: string[];
  /** Project-relative paths left untouched because they already exist. */
  skipped: string[];
}

function toPosix(path: string): string {
  return path.split(sep).join('/');
}

/** Resolves `rel` under `root`, refusing absolute paths and anything that escapes `root`. */
function resolveInside(root: string, rel: string, label: string): string {
  if (typeof rel !== 'string' || rel.length === 0 || isAbsolute(rel)) {
    throw new ProInstallError(`Invalid ${label} path in ${PRO_MANIFEST_FILE}: "${rel}"`);
  }
  const full = resolve(root, rel);
  const fromRoot = relative(root, full);
  if (fromRoot.startsWith('..') || isAbsolute(fromRoot)) {
    throw new ProInstallError(`${label} path "${rel}" escapes its directory`);
  }
  return full;
}

export function readProManifest(sourceDir: string): ProManifest {
  const manifestPath = join(sourceDir, PRO_MANIFEST_FILE);
  if (!existsSync(manifestPath)) {
    throw new ProInstallError(`No ${PRO_MANIFEST_FILE} found in ${sourceDir}`);
  }
  let manifest: ProManifest;
  try {
    manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as ProManifest;
  } catch (err) {
    throw new ProInstallError(
      `${PRO_MANIFEST_FILE} is not valid JSON: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
  if (!manifest.name || !manifest.version || !Array.isArray(manifest.install)) {
    throw new ProInstallError(`${PRO_MANIFEST_FILE} must define name, version and install[]`);
  }
  return manifest;
}

function listFiles(dir: string): string[] {
  const files: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) files.push(...listFiles(full));
    else if (entry.isFile()) files.push(full);
  }
  return files;
}

export function installPro(options: ProInstallOptions): ProInstallResult {
  const sourceDir = resolve(options.sourceDir);
  const targetDir = resolve(options.targetDir);
  const manifest = readProManifest(sourceDir);

  // Resolve every mapping before writing anything, so a bad entry aborts cleanly.
  const plan: Array<{ src: string; dest: string; rel: string }> = [];
  for (const mapping of manifest.install) {
    const from = resolveInside(sourceDir, mapping.from, 'from');
    const to = resolveInside(targetDir, mapping.to, 'to');
    if (!existsSync(from)) {
      throw new ProInstallError(`Manifest source "${mapping.from}" does not exist`);
    }
    const sources = statSync(from).isDirectory() ? listFiles(from) : [from];
    for (const src of sources) {
      const dest = statSync(from).isDirectory() ? join(to, relative(from, src)) : to;
      plan.push({ src, dest, rel: toPosix(relative(targetDir, dest)) });
    }
  }

  const written: string[] = [];
  const skipped: string[] = [];
  for (const { src, dest, rel } of plan) {
    if (existsSync(dest) && !options.force && !isGeneratedFile(dest)) {
      skipped.push(rel);
      continue;
    }
    written.push(rel);
    if (!options.dryRun) {
      mkdirSync(dirname(dest), { recursive: true });
      copyFileSync(src, dest);
    }
  }

  if (!options.dryRun) {
    const recordPath = join(targetDir, PRO_RECORD_FILE);
    mkdirSync(dirname(recordPath), { recursive: true });
    writeFileSync(
      recordPath,
      `${JSON.stringify(
        {
          name: manifest.name,
          version: manifest.version,
          installedAt: new Date().toISOString(),
          files: plan.map((p) => p.rel).sort(),
        },
        null,
        2,
      )}\n`,
      'utf8',
    );
  }

  return { name: manifest.name, version: manifest.version, written, skipped };
}
